// This code has been fully generated by an AI.
//
// Statistics page: bars per month/week with metric switch and cumulative
// distance per year compared with earlier years and the goal.

import uPlot from "./vendor/uplot-1.6.32/uPlot.esm.js";
import { METRICS, barSeries, cumulativeSeries, monthTicks, yearColor, labelStep, referenceIndex } from "./stats-data.js";
import { axisStyle, withAlpha } from "./theme-data.js";
import { chartColors, onThemeChange } from "./theme.js";

const fmt = (v, digits = 0) => (v == null ? "–" : v.toLocaleString("de-DE", { maximumFractionDigits: digits }));
const compact = (el) => el.clientWidth < 520;

export function showStats() {
  const data = JSON.parse(document.getElementById("chart-data").textContent);
  const group = document.getElementById("metric");
  let metric = "km";
  let bars, cumulative;
  const draw = () => {
    bars?.destroy();
    cumulative?.destroy();
    const colors = chartColors();
    bars = drawBars(document.getElementById("bars"), document.getElementById("bars-readout"), data, metric, colors);
    cumulative = drawCumulative(document.getElementById("cumulative"), document.getElementById("cumulative-legend"), data, colors);
  };
  draw();
  onThemeChange(draw);

  group.addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-metric]");
    if (!btn) return;
    for (const b of group.querySelectorAll("button")) b.setAttribute("aria-pressed", String(b === btn));
    metric = btn.dataset.metric;
    bars.setMetric(metric);
  });
}

/** Bars per month or week; the hovered bar is shown in the readout line. */
function drawBars(container, readout, data, metric, colors) {
  const width = () => container.clientWidth;
  const height = () => (compact(container) ? 200 : 240);
  let m = METRICS[metric];
  const { x, y } = barSeries(data, metric);
  const total = (values) => `${data.labels.length > 12 ? "Jahr" : "Summe"}: ${fmt(values.reduce((a, v) => a + (v ?? 0), 0), m.digits)} ${m.unit}`;
  readout.textContent = total(y);
  const plot = new uPlot({
    width: width(),
    height: height(),
    legend: { show: false },
    cursor: { drag: { x: false, y: false }, points: { show: false } },
    scales: { x: { time: false, range: [-0.6, x.length - 0.4] }, y: { range: (u, min, max) => [0, Math.max(1, max * 1.1)] } },
    axes: [
      axisStyle(colors, {
        values: (u, ticks) => {
          const step = labelStep(data.labels.length, u.bbox.width / devicePixelRatio);
          return ticks.map((t) => (t % step === 0 ? data.labels[t] ?? "" : ""));
        },
        splits: () => x,
        grid: { show: false },
        gap: 4,
        size: 28,
      }),
      axisStyle(colors, { size: 48, values: (u, ticks) => ticks.map((t) => fmt(t)) }),
    ],
    series: [
      {},
      {
        stroke: colors.accent,
        fill: withAlpha(colors.accent, 0.75),
        paths: uPlot.paths.bars({ size: [0.7, 60] }),
        points: { show: false },
      },
    ],
    hooks: {
      setCursor: [
        (u) => {
          const i = u.cursor.idx;
          readout.textContent = i == null ? total(u.data[1]) : `${data.labels[i]}: ${fmt(u.data[1][i], m.digits)} ${m.unit}`;
        },
      ],
    },
  }, [x, y], container);

  const resize = new ResizeObserver(() => plot.setSize({ width: width(), height: height() }));
  resize.observe(container);
  return {
    setMetric(next) {
      m = METRICS[next];
      const values = barSeries(data, next).y;
      plot.setData([x, values]);
      readout.textContent = total(values);
    },
    destroy() {
      resize.disconnect();
      plot.destroy();
    },
  };
}

function drawCumulative(container, legendEl, data, colors) {
  const { x, series } = cumulativeSeries(data);
  const ticks = monthTicks();
  const width = () => container.clientWidth;
  const height = () => (compact(container) ? 240 : 280);
  const strokes = series.map((s, i) => (s.goal ? colors.muted : colors.years[i] || yearColor(i)));

  // Own legend instead of uPlot's: uPlot shows values only while hovering,
  // which never happens on touch screens. Without cursor it shows the
  // reference day (today or year end) for all years.
  const ref = referenceIndex(series);
  const day = document.createElement("p");
  day.className = "legend-day";
  const list = document.createElement("ul");
  list.className = "legend";
  const outputs = series.map((s, i) => {
    const li = document.createElement("li");
    const sw = document.createElement("span");
    sw.className = s.goal ? "swatch goal" : "swatch";
    sw.style.setProperty("--swatch", strokes[i]);
    const label = document.createElement("span");
    label.textContent = s.goal ? "Ziel" : s.label;
    const out = document.createElement("output");
    li.append(sw, label, out);
    list.append(li);
    return out;
  });
  legendEl.replaceChildren(day, list);
  const showDay = (i) => {
    if (i == null || i < 0) i = ref;
    if (i < 0) {
      day.textContent = "";
      outputs.forEach((o) => (o.textContent = "–"));
      return;
    }
    day.textContent = `Stand ${dayLabel(x[i])}`;
    series.forEach((s, j) => (outputs[j].textContent = s.values[i] == null ? "–" : `${fmt(s.values[i])} km`));
  };
  showDay(ref);

  const plot = new uPlot({
    width: width(),
    height: height(),
    legend: { show: false },
    cursor: { drag: { x: false, y: false } },
    scales: { x: { time: false, range: [1, 366] }, y: { range: (u, min, max) => [0, Math.max(10, max * 1.05)] } },
    axes: [
      axisStyle(colors, {
        splits: () => ticks.values,
        values: (u) => ticks.labels.map((l, i) => (compact(container) && i % 2 ? "" : l)),
        size: 28,
      }),
      axisStyle(colors, { size: 52, values: (u, t) => t.map((v) => fmt(v)) }),
    ],
    series: [
      {},
      ...series.map((s, i) => ({
        stroke: strokes[i],
        width: s.goal ? 1.5 : i === 0 ? 2.5 : 1.5,
        dash: s.goal ? [6, 4] : undefined,
        points: { show: false },
      })),
    ],
    hooks: { setCursor: [(u) => showDay(u.cursor.idx)] },
  }, [x, ...series.map((s) => s.values)], container);
  const resize = new ResizeObserver(() => plot.setSize({ width: width(), height: height() }));
  resize.observe(container);
  return {
    destroy() {
      resize.disconnect();
      plot.destroy();
      legendEl.replaceChildren();
    },
  };
}

function dayLabel(dayOfYear) {
  // Day of a non-leap year is sufficient for the tooltip.
  const d = new Date(Date.UTC(2025, 0, dayOfYear));
  return d.toLocaleDateString("de-DE", { day: "numeric", month: "short", timeZone: "UTC" });
}
